#ifdef NDEBUG
#error "Tests require assertions enabled; do not define NDEBUG."
#endif
#include <array>
#include <cassert>
#include <cstddef>
#include <vector>

// 위험·보상 규칙과 표현 상태를 분리하는 교육용 CPU 모델.
// 3x3 방에 색상 블록을 놓는다. 네트워크·저장·렌더링은 포함하지 않는다.
enum class Mode { Free, Budget };
enum class Result { Changed, NoChange, InvalidInput, NoBudget, NoHistory };
struct State {
    std::array<int, 9> cells; // 0=빈칸, 1~3=색상
    int budget;
};
class RoomModel {
    Mode mode_;
    State state_;
    std::vector<State> history_; // 성공한 편집 직전 상태만 저장한다.
public:
    explicit RoomModel(Mode mode) : mode_(mode), state_{{{0,0,0,0,0,0,0,0,0}}, 3} {}
    const State& Get() const { return state_; }
    std::size_t UndoCount() const { return history_.size(); }
    Result Paint(int cell, int color) {
        if (cell < 0 || cell >= 9 || color < 0 || color > 3)
            return Result::InvalidInput;
        if (state_.cells[static_cast<std::size_t>(cell)] == color)
            return Result::NoChange;
        // 예산 모드는 '실제 상태가 바뀌는 편집 1회'마다 1을 쓴다.
        // 지우기(color=0)도 편집이다. 무료 모드는 비용이 없다.
        if (mode_ == Mode::Budget && state_.budget == 0)
            return Result::NoBudget;
        history_.push_back(state_); // 할당 실패 시 현재 상태는 아직 바뀌지 않는다.
        state_.cells[static_cast<std::size_t>(cell)] = color;
        if (mode_ == Mode::Budget) --state_.budget;
        return Result::Changed;
    }
    Result Undo() {
        if (history_.empty()) return Result::NoHistory;
        state_ = history_.back();
        history_.pop_back(); // 예산도 되돌린다. 실패 벌점이 없는 실험 계약이다.
        return Result::Changed;
    }
};
static bool Equal(const State& a, const State& b) {
    return a.cells == b.cells && a.budget == b.budget;
}
int main() {
    RoomModel freeRoom(Mode::Free);
    const State empty = freeRoom.Get();
    assert(freeRoom.Undo() == Result::NoHistory);
    assert(freeRoom.Paint(-1,1) == Result::InvalidInput);
    assert(freeRoom.Paint(9,1) == Result::InvalidInput);
    assert(freeRoom.Paint(0,-1) == Result::InvalidInput);
    assert(freeRoom.Paint(0,4) == Result::InvalidInput);
    assert(Equal(empty,freeRoom.Get()) && freeRoom.UndoCount() == 0);
    assert(freeRoom.Paint(0,0) == Result::NoChange);
    assert(freeRoom.Paint(0,1) == Result::Changed);
    assert(freeRoom.Paint(0,1) == Result::NoChange);
    assert(freeRoom.UndoCount() == 1);
    assert(freeRoom.Paint(0,0) == Result::Changed); // 지우기도 취소 가능
    assert(freeRoom.Undo() == Result::Changed && freeRoom.Get().cells[0] == 1);
    assert(freeRoom.Undo() == Result::Changed && Equal(empty,freeRoom.Get()));
    RoomModel budgetRoom(Mode::Budget);
    for (int i=0; i<3; ++i) assert(budgetRoom.Paint(i,i+1) == Result::Changed);
    assert(budgetRoom.Get().budget == 0);
    assert(budgetRoom.Paint(0,1) == Result::NoChange); // 무변경은 예산 없어도 성공 판정 아님
    const State exhausted = budgetRoom.Get();
    assert(budgetRoom.Paint(3,1) == Result::NoBudget);
    assert(Equal(exhausted,budgetRoom.Get()) && budgetRoom.UndoCount() == 3);
    assert(budgetRoom.Undo() == Result::Changed && budgetRoom.Get().budget == 1);
    assert(budgetRoom.Paint(8,3) == Result::Changed && budgetRoom.Get().budget == 0);
    // 10,000회 편집 후 모두 취소하면 최초 상태를 정확히 복구한다.
    RoomModel stress(Mode::Free);
    for (int i=0; i<10000; ++i) {
        const int cell = i % 9;
        const int color = (stress.Get().cells[static_cast<std::size_t>(cell)] + 1) % 4;
        assert(stress.Paint(cell,color) == Result::Changed);
    }
    assert(stress.UndoCount() == 10000 && stress.Get().budget == 3);
    while (stress.UndoCount() != 0) assert(stress.Undo() == Result::Changed);
    assert(Equal(empty,stress.Get()));
}
